"""Render Chinese HTML/TXT, paper prose and all set-specific LaTeX from measured data."""
import csv,html,datetime,json,math
from collections import Counter
from common import *
from finalize_tables import LABELS,PANEL
REPORT=E/'report';REPORT.mkdir(exist_ok=True)
def csvread(name):return list(csv.DictReader((E/'tables'/name).open()))
def num(x,d=2,percent=False):
    if x in [None,'','None']:return '—'
    if x=='inf':return '∞'
    return f'{float(x)*(100 if percent else 1):.{d}f}'
def main():
    progress=read(E/'progress.json');ledger=read(E/'geometry_ledger.json')['rows'];refs=read(E/'reference_manifest.json')['rows'];stats=csvread('geometry_summary.csv');times=csvread('time_summary.csv');runs=csvread('time_per_run.csv');sets=read(E/'tables/common_and_paired_sets.json');audit=read(E/'validation/geometry_independent_audit.json');ev=read(E/'validation/geometry_evidence_audit.json')
    finished=progress['geometry_terminal']==600 and progress['time_terminal']==20 and all(r['status']=='failed' or r['independent_reload_status']=='passed' for r in runs)
    state='全部计划已终结，详见完成审计' if finished else f'几何已完成；Time 已终结 {progress["time_terminal"]}/20，尚未宣称整项完成'
    sections=[]
    def sec(title,paragraphs=(),table=None,fig=None):sections.append(dict(title=title,paragraphs=list(paragraphs),table=table,fig=fig))
    def metric_table(rows):
        return (['方法','N','有限 / 空','CD扩展均值 cm','CD有限均值 cm','CD有限中位 cm','F1@5 %','F1@10 %','F1@20 %','RayHit %','RayAcc@10 %'],[[LABELS[r['method']],r['n'],r['n_finite']+' / '+r['n_empty'],num(r['cd_extended_mean_cm']),num(r['cd_finite_mean_cm']),num(r['cd_finite_median_cm']),num(r['f1_5cm'],percent=True),num(r['f1_10cm'],percent=True),num(r['f1_20cm'],percent=True),num(r['ray_hit'],percent=True),num(r['ray_acc_10cm'],percent=True)] for r in rows])
    def subset(pop='main',condition=PANEL,name='own'):return [r for r in stats if r['reference_population']==pop and r['condition']==condition and r['set']==name]
    counts=Counter(r['geometry_status'] for r in ledger)
    sec('执行状态与主要结果',[state,'本次在冻结的100个人物、67个实际场景、既定真实曝光时刻及六种方法的现有资产上完成几何补测。600条账本中，527条具有有限CD，1条为有效空预测，72条为有证据的NA；没有把NA填成零，也没有将低支持参考混进主表。','参考侧先于正式得分冻结：84人进入主参考候选并通过本轮身份、坐标和范围核查，16人保留为低支持探索性附表。六法主共同准入46人，主共同有限CD45人；这些名单由新几何资格重新求交，未把旧二维共同集当评分开关。','几何对528条可测记录逐条执行了独立暴力距离复算，包含183个额外native_metric面板，共711个面板通过。所有100人的原始索引、scan/标签哈希和q=o+r·u均核对通过。'])
    cover=[]
    for m in METHODS:
        rows=[r for r in ledger if r['method']==m];main=[r for r in rows if r['reference_panel']=='main'];low=[r for r in rows if r['reference_panel']!='main']
        cover.append([LABELS[m],100,sum(r['asset_available'] for r in rows),sum(r['geometry_status']=='scored' for r in main),sum(r['geometry_status']=='empty_pred' for r in main),sum(r['geometry_status']=='scored' for r in low),sum(r['geometry_status'].startswith('NA') for r in rows),sum(r['registration_recovered'] for r in rows)])
    sec('覆盖与最终去向',['图中浅蓝是低支持参考的有限CD，不能与深蓝主参考数相加后称为同等可靠的100人成绩。TRELLIS.2的有效空预测是HN0181；其参考、源关系、尺度和适配器正常，但固定查询没有达到有效返回条件。'],(['方法','冻结人数','原生资产存在','主有限CD','主空预测','低支持有限CD','NA','新增源配准'],cover),'coverage')
    sec('从真实scan到分数',['每人取与冻结相机曝光同sample的官方有类别标签LiDAR keyframe。逐点核对扫描和标签顺序，用目标类别、目标有向标注框和唯一同类框归属筛点；4个同类框归属歧义点被剔除。按原始索引顺序，每个5cm体素只保留首个真实回波，而非体素中心。所得100组参考最少7、中位38、最多108个点；84组至少20点。','将LiDAR传感器原点o与真实端点q同时按该scan的sensor/ego标定变到world。记录r=||q−o||和u=(q−o)/r，保存scan token、原始索引和变换。每个方法只在这些固定真实方向查询深度；即使某条查询未命中，也保留对应真实端点G。','相机与scan绝对时差为0.200–44.879ms，中位34.8415ms。50ms仅是近同步工程门槛，并非肢体误差上界。没有跨帧拼点、人体整体SE3运动补偿、逐束时刻或去畸变证明，故这里只使用标称scan射线。类别加唯一框筛选亦不等于独立逐点实例真值。','全部参考投影联系图已由Codex直接检查，未发现明显错人或大块背景归属；这不是独立人工盲审。可见邻人、栏杆、背包、手持物、雨伞和坐姿等范围不确定性保留在references/visual_review.json。标注框高度是垂直范围，不是解剖身高。'],fig='reference_support')
    sec('尺度、位置与外部信息',['主条件命名annotation_vertical_extent_conditioned。先保留已核验的真实源相机关系，去除该关系中的任意整体相似尺度。按真实相机外参与重力，将完整原生表示投影到六个正交方向；所有方向均尝试，不删原语、不裁掉低透明度点，不按分位数修模型。','尺寸支持采用round(255·alpha)>127，与查询alpha≥0.5同义。以所有非空侧视图的世界重力轴上下端并集测h_native，至少要求一对相对侧视图有支持；真正薄片的正交边缘视图可为空，并保留其证据。技术错误或裁切不能视作正常空图通过。','512→1024起步，边界差≤高度1%、细像素宽≤高度0.5%才通过；必要时统一升2048/4096。实际524条在1024通过，4条升到2048；最大边界差比例0.8231%，最大细像素比例0.4049%。全部6360张支持图均绑定哈希。完整三轴尺寸诊断中的旧formal_metrics_qualified=false不参与本实验：本次只认证重力轴高度，正式资格见vertical precision.passed。','h_annotation由标注框8角在world重力轴的极差计算。令s=h_annotation/h_native，若源关系为X_cam=R·X_native+t，则X_world=T_world_from_camera·[s(R·X_native+t)]。平移也乘s，协方差相应为s²RΣRᵀ。未做ICP、LiDAR端点拟合、各向异性缩放、关节纠正或标注中心对齐。','给模型的额外信息包括参考筛选所需身份/类别/标注框，以及统一尺度条件所需重力与标注垂直范围；源相机关系还依赖源RGB中的语义对应。消除的是任意整体尺度，并保留源投影关系；剩余误差混合了生成形状、姿态、全局朝向/位置、完整alpha范围与近同步参考误差。','对本来有world米制坐标的场景方法，强制高度条件化也会改变相机到对象的距离；该面板不代表其原生米制定位能力。OmniRe/SplatAD另列native_metric，二者不能与条件化分数混成一个总平均。'])
    sec('原生表示、时间与深度',['Ours使用当前4DAnyone Turbo＋Grid4D资产在既定t_ref的原始非循环时钟快照，保留完整SH3、协方差和root/time来源；已有100份质量快照中57份为连续插值、43份在原生端点。本轮几何没有重新训练这100人，也没有换成静态Splatfacto。','AH使用原生Gaussian PLY；TRELLIS原版使用原生Gaussian PT；TRELLIS.2使用含几何及材质体素的MeshWithVoxel PT。OmniRe使用非SMPL DeformableNodes在同一物理曝光时刻的状态；SplatAD使用原生actor轨迹与几何参数。场景checkpoint、actor身份、时间映射和必要解码器来源均绑定证书。输出肢体或姿态错误完整保留。','Gaussian使用原生alpha权重w_i：A=Σw_i，Dz=Σ(w_i z_i)，ED=Dz/A。先插值A和Dz，再相除，并用u_cam,z将条件期望相机z转成射线range。高斯中心不是表面。TRELLIS与SplatAD仅正交尺寸测量使用经验证的替代alpha实现；正式透视查询仍走各自原生内核。','TRELLIS.2沿用原生体素alpha三线性采样与SSAA2，累计同样的A/Dz；起始8层depth peeling，若下一有效层剩余透射>1e−4则统一升16/32/64，64仍不收敛即失败。实际704次尺寸/查询渲染中703次使用8层，HN0181的一次查询使用16层；收敛后仍为空预测。未换为不透明BVH首交，也未给原生PT套用GLB坐标变换。','所有正式查询使用6个90°虚拟相机扇区、1024分辨率，仅渲染有查询的扇区；alpha≥0.5且range∈[0.1,200]m才算返回。Gaussian的ED是透明度加权深度，体素网格则是多层表面alpha加权深度，二者共享观测定义但不被解释成同一种真实封闭表面。'])
    sec('统一配准修复与剩余NA',['54条“资产存在而源关系不足”的记录全部经过一轮公共修正及证据复核：原16视图、按统一内容框放大后检测、至少3视图三角化、置信度>0.5、重投影≤8px、有效视差≥10°、至少6个身体对应及正深度全局SQPnP。只解一个全局关系。','跨相反面视图的镜像纹理曾将左右关节折叠，初始候选因此被拒绝。随后统一检查中心0/4/8/12、各±2视图的固定局部邻域。依据语义对应而非CD/F1，接受TRELLIS HN0517的9个对应及TRELLIS.2 HN0263的11个对应；二者都使用第一个可语义确认的中心0邻域。原有缺腿或姿态错误未修正。','恢复数：Ours 0、AH 0、TRELLIS 1、TRELLIS.2 1、OmniRe 0、SplatAD 0。剩余TRELLIS 8、TRELLIS.2 44共52条，统一修正及直接视觉核验后仍无法确认足够可靠的全局人体对应。部分仍可辨认残缺人体，不把“检测器没检出”单独当不可测的证明，也不声称未来任何人工标注都绝无恢复可能。全部逐项证据、对应点数及联系图位置在failure_reasons.csv。','SplatAD缺失16人：核查已有checkpoint/actor UUID、所有相关正式导出及原生parser后，16人均被原生静止轨迹过滤排除，XY标准差均未超过0.5m；没有通过取消过滤重训。OmniRe HN0397经一次原生初始化重提取仍被排除，目标轨迹长0.333973m，低于原规则0.5m；现有67个DeformableNodes的规模与可见性均与原生初始化顺序吻合。','未从背景Gaussian截取一个框就冒充人物：缺少独立actor身份和实例隔离，框内可同时含地面及邻近背景，因此没有生成annotation-assisted区域面板。TRELLIS.2的HN0292/HN0834/HN0861保留原生生成失败（空张量max()异常），未换种子抽取成功。'],(['NA原因','人数×方法记录'],[['源对应仍无法可靠建立',52],['SplatAD原生静止过滤',16],['OmniRe原生初始化过滤',1],['TRELLIS.2原生生成失败',3]]))
    sec('指标与解释',['令G为固定真实端点，P为同批查询得到的有效预测端点。CD=½[mean_p min_g ||p−g||₂ + mean_g min_p ||g−p||₂]，未平方L2，内部单位米、展示厘米；双向分量保留在逐人CSV。Precision@τ为P到G最近距离严格小于τ的比例，Recall@τ反向计算；F1=2PR/(P+R)，零分母取0。τ固定为5/10/20cm，10cm为主阈值。','RayHit=有效返回数/固定查询数；RayAcc@τ=命中且同射线range误差严格小于τ的数量/全部查询数。没有真实无回波负射线，所以它不是完整ray-drop accuracy。','正常可重载但没有有效返回时，F1、RayHit、RayAcc均为0，CD=null，扩展CD均值为∞；有限CD统计必须同时给n_finite/n_empty。NA则为参考/资产/关系等必要条件缺失，不能当空预测或零分。每人先评分再等权汇总，未按回波数量加权。','主表衡量的是固定可观察射线上的近同步稀疏几何一致性，不是完整人体表面、背面补全或动作质量。不同方法自身可测集合存在选择偏差，不能直接据其均值排名。共同有限集去掉空预测，也会产生成功条件偏差，因此必须与共同准入表、覆盖和失败表并列。'])
    sec('主共同准入集合：46人',['六法使用相同46人。TRELLIS.2包含HN0181空预测，扩展CD为∞；其有限CD列仅45人，不能与其他方法46人的有限均值直接作同人比较。F1/Ray指标仍在46人上包含该零返回记录。'],metric_table(subset(name='common_admission')))
    sec('主共同有限CD集合：45人',['对六法共同准入集再统一去掉任一方法CD为空的人，六法均在同一45人上计算。橙色菱形为人等权均值，箱图为中位数和四分位，蓝点保留各人值；图左使用对数纵轴，并未截掉长尾。'],metric_table(subset(name='common_finite_cd')),'common_scores')
    sec('各法自身可测主集合',['这些集合分别为84、84、79、51、83、72人；其中TRELLIS.2为50有限+1空。只能用于描述覆盖和自身条件表现，不能据此横向排名。'],metric_table(subset()))
    for baseline in METHODS[1:]:
        sec('Ours 与 '+LABELS[baseline]+'：同人配对',['下表为共同准入配对；相应共同有限版本以及两套完整ID名单同样交付。若包含空预测，有限版本对两法同时去掉该人。'],metric_table(subset(name='ours_vs_'+baseline+'/admission')))
    sec('低支持探索性附表',['16个参考不足20点的人全部保留。六法各自可测数为16、16、13、2、16、12；六法低支持共同集为空，因此没有制造一张空共同表的零分。完整低支持同人配对仍在CSV/LaTeX中。'],metric_table(subset(pop='low_support_exploratory')))
    sec('原生米制场景面板',['OmniRe/SplatAD在通过world尺度和同一物理时刻核验后直接使用原生映射，未套用标注高度。下表为主参考同人72人。它与主条件化表回答不同问题；本轮没有重测场景训练时间或将其填为0。原生米制自身集合83/72人，以及低支持自身16/12、共同12人的结果也单独交付。'],metric_table(subset(condition='native_metric',name='common_admission')))
    sec('固定开发样本的射线诊断',['HN0004是先于正式评分选定的开发身份。图中每个索引对应同一条真实查询；蓝点为有返回的有符号range误差，橙色叉为未返回，绿带为±10cm。此图只解释深度查询，不用于选择模型、配准或统计集合。'],fig='pilot_ray_errors')
    sec('Time设计与边界',['正式计划为四个直接方法×四人，并为首名锚点各追加一次重复，共20次。人物固定为HN0040、HN0136、HN0317、HN0249；按输入时长/曝光数、原生像素高度分层、姿态元数据轮换与带盐ID哈希确定，未使用模型成功、LiDAR支持或质量分数选人。四人各有30个真实曝光，原始片段约2.4–2.45s；HN0040为重复锚点。','名称为“分阶段预加载条件下的资产生成时间”。从冻结真实输入本地可用、相关预训练权重就绪开始，计入方法专有预处理、姿态/相机估计、生成、逐人优化、必要内存搬运、阶段读写与原生保存，GPU同步后结束；下载、排队、一次性模型构造、预览、环绕、配准/指标和独立重载验收排除。','Ours实际重做原始裁剪、RIFE插帧、分割、运动估计、条件构建、Turbo 24视图×61帧、必要掩码和初始化、Grid4D 32999+15000+5000次更新、完整SH3/协方差原生导出及精确t_ref快照。按原始配方使用21个训练视图，排除0/8/16；完整native权重、时钟、root metadata保留。没有加载已有最终资产充当生成，也没有省略逐人优化。','Ours的计时wrapper在明确的预训练构造/权重加载入口暂停、同步后恢复，保存全部active/load区间并求和；训练阶段不启用逐调用profiling。生成状态的阶段交接和必要加载仍计入。只移除了预览或独立验收用渲染，原始优化预算、损失、采样及随机状态保持；预处理阶段的计时监测开销保留，不估计扣除。','AH包含原生相机估计、30步多视图生成、Gaussian lifting及PLY和相机元数据保存；TRELLIS使用原25/25步Gaussian配置及原生PT/等价PLY保存；TRELLIS.2使用1024_cascade、low_vram、max_num_tokens=49152、seed42，包含形状和材质体素、必要simplify与MeshWithVoxel PT保存。人体T2终点不同于刚体纹理GLB，不直接拿二者时间当同一产品成本。','四法计时使用同一张RTX4090 GPU4独占锁、各方法原有软件/质量配置；没有为了表面统一升级环境。Trellis PyTorch2.4/CUDA12.1、T2 2.6/12.4、AH 2.10/12.8；Ours各阶段沿用原环境，版本逐阶段记录。计时不含排队，不并行跑多个Ours去把吞吐时间当单资产延迟。CPU、存储、GPU进程与剩余磁盘记录随每次运行保存；Ours另有30秒采样。','首次实际内核编译若进入正式区间则保留，不以历史耗时估计扣减。AH初次包装的ndarray JSON序列化错误发生在原生推理完成之后；修复公共保存包装后对固定五次计划重新测量，原始五次基础设施失败与日志保留，不伪称原生模型五次失败。正式失败不换人、不改种子。','汇总先将锚点重复在人物内平均，再对成功人物等权；同时列出成功/尝试次数、全部逐次秒数、范围和逐阶段耗时。这里是4人的小样本条件均值，不是冻结100人的平均、置信区间或相同输出功能下的严格速度消融。'])
    time_table=(['方法','成功 / 计划','失败','待完成','成功人物','人物等权均值 s','人物均值中位 s','逐次最小–最大 s'],[[LABELS[r['method']],r['n_success']+' / '+r['n_planned'],r['n_failed'],r['n_pending'],r['n_successful_people'],num(r['person_equal_weight_mean_seconds']),num(r['person_equal_weight_median_seconds']),num(r['min_seconds'])+'–'+num(r['max_seconds']) if r['n_planned']!='0' else '不适用/本轮不测'] for r in times])
    sec('Time实测汇总',[state,'所有成功端点均须通过计时之外的独立重载；Ours另以全新进程加载原生网络权重，对原始/导出数组、完整SH3、协方差、非循环快照和全部优化步数进行核查。尚未完成或未验收的条目不能用阶段小计代替完整生成Time。','Ours五次均在导出计时启动前触发同一包装命名空间错误。全部15个已完成的真实生成阶段、完整52999次更新及其原始实测区间保留；统一使用inspect.unwrap修复包装后，只补测尚未执行的导出和快照。跨时段的分阶段区间相加符合预先允许的计时口径，但不是连续墙钟延迟。失败控制器记录与原日志另行归档，未重训五个样本，也未把加载训练终点本身报成完整生成。','单图方法使用已冻结的目标ROI及其输入mask/RGBA，基准目标隔离的创建不计入本轮生成；原生方法自身的读入、裁剪、相机估计或背景预处理仍计入。Ours按原始生产链从30个真实曝光重建必要输入，其专有前处理计入。实际输入路径和哈希见timing/input_bindings.json。'],time_table)
