    sec('逐项NA附表：72条',[],(headers,failure_rows))
    stamp=datetime.datetime.now(datetime.timezone.utc).isoformat();textparts=['人体100人 CD / F1 / Time 实验与执行报告',state,'生成时间UTC：'+stamp,'主协议SHA256：'+sha(E/'protocol.json'),'冻结选择SHA256：'+SELECTION_SHA]
